import{_ as e,o as t,c as s,a2 as n}from"./chunks/framework.D4up2k3b.js";const i="/filebox/docs/screenshots/05-terminal.png",u=JSON.parse('{"title":"远程终端 Terminal","description":"","frontmatter":{},"headers":[],"relativePath":"features/terminal.md","filePath":"features/terminal.md","lastUpdated":null}'),l={name:"features/terminal.md"};function r(o,a,h,p,g,d){return t(),s("div",null,[...a[0]||(a[0]=[n('<h1 id="远程终端-terminal" tabindex="-1">远程终端 Terminal <a class="header-anchor" href="#远程终端-terminal" aria-label="Permalink to &quot;远程终端 Terminal&quot;">​</a></h1><p>可选功能：在浏览器里开 Agent 本机的交互式 shell。<strong>未沙箱</strong>——能做该 OS 用户能做的一切。务必只在可信环境启用。</p><p><img src="'+i+`" alt="Remote Terminal"></p><h2 id="启用-2fa-agent-本机" tabindex="-1">启用 2FA（Agent 本机） <a class="header-anchor" href="#启用-2fa-agent-本机" aria-label="Permalink to &quot;启用 2FA（Agent 本机）&quot;">​</a></h2><p>密钥只存在 Agent 上；Hub <strong>只转发</strong>验证码做本地校验，从不保存 TOTP 密钥。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --setup-terminal-2fa</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 或指定配置：</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --setup-terminal-2fa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/agent.toml</span></span></code></pre></div><p>按向导把密钥写入 Authenticator 后，<strong>重启 Agent</strong>。也可用环境变量 <code>FILEBOX_AGENT_TERMINAL_TOTP_SECRET</code>（base32，至少 16 字节；环境变量优先；无效值会导致启动失败，不会静默降级）。</p><p>每次打开 / 恢复会话都要提交新的 TOTP。</p><h2 id="会话" tabindex="-1">会话 <a class="header-anchor" href="#会话" aria-label="Permalink to &quot;会话&quot;">​</a></h2><ul><li>浏览导航、断线、Hub 重启、空闲后 shell 仍可 <strong>Resume</strong>。</li><li>用 Sessions → <strong>Resume</strong> 重连，或 <strong>End</strong> 结束。</li><li>Agent <strong>进程重启</strong>会丢失会话；回放最近约 <strong>256 KiB</strong> 输出。</li></ul><h2 id="安全提醒" tabindex="-1">安全提醒 <a class="header-anchor" href="#安全提醒" aria-label="Permalink to &quot;安全提醒&quot;">​</a></h2><ul><li>终端能力等于该 Agent 的 OS 用户权限。</li><li>不要在共享或不信任的机器上启用。</li><li>版本对齐：Hub / Agent / 前端大版本建议一起升（见 release notes）。</li></ul><p>相关：<a href="./security">安全与敏感文件</a> · <a href="/filebox/docs/ops/agent">Agent 运维</a></p>`,13)])])}const m=e(l,[["render",r]]);export{u as __pageData,m as default};
